    let lush = mix(vec3f(0.07, 0.127, 0.024), vec3f(0.108, 0.162, 0.03), fract(h.y * 3.7));
    let straw = smoothstep(0.86, 1.0, tuft) * 0.25 + smoothstep(0.8, 0.97, patchy) * 0.12;
